// LWW register: only keep the update with the highest timestamp
interface LWWRegister<T> {
  value: T;
  timestamp: number;  // logical or wall-clock timestamp
}

function merge<T>(local: LWWRegister<T>, remote: LWWRegister<T>): LWWRegister<T> {
  // Higher timestamp wins; ties favour the local value
  return remote.timestamp > local.timestamp ? remote : local;
}

// Example: user status update
const local  = { value: 'online',  timestamp: 1700000010 };
const remote = { value: 'offline', timestamp: 1700000015 };
console.log(merge(local, remote).value); // 'offline' — remote wins

// Upcaster: transform UserRegistered v1 → v2 (split fullName)
interface UserRegisteredV1 { version: 1; userId: string; fullName: string; email: string; }
interface UserRegisteredV2 { version: 2; userId: string; firstName: string; lastName: string; email: string; }

function upcastUserRegistered(raw: UserRegisteredV1): UserRegisteredV2 {
  const [firstName, ...rest] = raw.fullName.split(' ');
  return {
    version: 2,
    userId: raw.userId,
    firstName,
    lastName: rest.join(' ') || '',
    email: raw.email,
  };
}

