// CQRS command bus with middleware (NestJS CqrsModule)
import { CommandBus, CommandHandler, ICommandHandler } from '@nestjs/cqrs';

class PlaceOrderCommand {
  constructor(readonly customerId: string, readonly items: Item[]) {}
}

@CommandHandler(PlaceOrderCommand)
class PlaceOrderHandler implements ICommandHandler<PlaceOrderCommand> {
  async execute(cmd: PlaceOrderCommand): Promise<void> {
    // Business logic — bus handles middleware around this
    const order = Order.create(cmd.customerId, cmd.items);
    await this.orderRepo.save(order);
  }
}

// Sender — does not import PlaceOrderHandler
