async function loadAggregate(aggregateId: string): Promise<OrderAggregate> {
  // 1. Find the most recent snapshot
  const snapshot = await eventStore.loadSnapshot(aggregateId);
  const fromVersion = snapshot?.version ?? 0;
  const baseState   = snapshot?.state   ?? OrderAggregate.empty();

  // 2. Load only delta events after the snapshot
  const deltaEvents = await eventStore.loadEvents(aggregateId, { fromVersion });

  // 3. Replay delta onto snapshot state
  return deltaEvents.reduce(apply, baseState);
}

// Rebuild a projection from scratch via full replay
async function rebuildOrderSummaryProjection(): Promise<void> {
  await db.truncate('order_summaries'); // start fresh

  const stream = eventStore.streamAll({ eventTypes: ['OrderPlaced', 'OrderShipped', 'OrderCancelled'] });

  for await (const event of stream) {
    await orderSummaryProjection.handle(event);
  }

  console.log('Projection rebuilt from event log.');
}

// ODD: every significant operation instrumented at authoring time
func processPayment(orderId: String, amount: Decimal) async throws -> PaymentResult {
    let span = tracer.startSpan("payment.process",
        attributes: ["order.id": orderId, "payment.amount_cents": Int(amount * 100)])
    defer { span.end() }

    paymentAttempts.increment(labels: ["order_id": orderId])

    do {
        let result = try await gateway.charge(orderId: orderId, amount: amount)
        span.setStatus(.ok)
        logger.info("Payment succeeded", metadata: ["order_id": "\(orderId)", "transaction_id": "\(result.transactionId)"])
        return result
    } catch {
        span.recordError(error)
        paymentFailures.increment(labels: ["reason": error.localizedDescription])
        throw error
    }
}

