// Message versioning: explicit version field in event schema
type OrderPlacedV1 = { schemaVersion: 1; orderId: string; customerId: string; total: number; };
type OrderPlacedV2 = { schemaVersion: 2; orderId: string; customerId: string; total: number; channel: 'web' | 'mobile' | 'api'; };
type OrderPlaced = OrderPlacedV1 | OrderPlacedV2;

// Consumer handles multiple versions
function handleOrderPlaced(event: OrderPlaced): void {
  const channel = event.schemaVersion >= 2 ? event.channel : 'web';  // default for old messages
  processOrder(event.orderId, event.customerId, event.total, channel);
}

