// Write model — command handler enforces invariants
class AddItemCommandHandler {
  async handle(cmd: AddItemCommand): Promise<void> {
    // Load authoritative write model state
    const order = await this.orderRepo.findById(cmd.orderId);

    // Enforce business invariant
    if (order.status !== 'pending') {
      throw new BusinessRuleViolation('Cannot add items to a non-pending order');
    }

    order.addItem(cmd.item);

    // Persist atomically — write model + outbox in one transaction
    await this.orderRepo.saveWithOutbox(order);
  }
}

// Temporal query — rebuild state at a specific point in time
async function getOrderStateAt(orderId: string, atTime: Date): Promise<OrderState> {
  // Load only events that occurred at or before the target time
  const events = await eventStore.loadEvents(orderId, {
    toTimestamp: atTime,
  });

  if (events.length === 0) {
    throw new Error(`Order ${orderId} did not exist at ${atTime.toISOString()}`);
  }

  // Replay to reconstruct historical state
  return events.reduce(apply, {} as OrderState);
}

// Edge router: map tenant to cell by consistent hash
function routeToCell(tenantId: string, cellCount: number): number {
  // FNV-1a hash (deterministic — same tenant always maps to same cell)
  let hash = 2166136261;
  for (const byte of Buffer.from(tenantId, 'utf8')) {
    hash ^= byte;
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return hash % cellCount;
}

