// Append to an event stream with optimistic concurrency
async function appendEvents(
  streamId: string,
  events: DomainEvent[],
  expectedVersion: number
): Promise<void> {
  try {
    await eventStore.appendToStream(streamId, events, {
      expectedRevision: BigInt(expectedVersion),  // optimistic concurrency check
    });
  } catch (err) {
    if (err instanceof WrongExpectedVersionError) {
      throw new ConcurrencyConflict(
        `Stream ${streamId} was modified concurrently. Expected v${expectedVersion}.`
      );
    }
    throw err;
  }
}
